<#
  mem0-setup.ps1  --  single-file installer for the mem0 + opencode memory system.

  It carries the whole skill inside itself. Running it:
    1. materializes the skill into  ~/.config/opencode/skills/mem0-opencode-setup/
    2. runs that skill's install.ps1 (detect/remove other mem0 integrations, then install)

  One-liner (local):
    powershell -NoProfile -ExecutionPolicy Bypass -File mem0-setup.ps1 -ApiKey "m0-xxxx"

  One-liner (if hosted):
    powershell -NoProfile -Command "irm <raw-url> | iex"

  Options: -DryRun  -SkipCleanup  -SkillOnly  -ApiKey "m0-..."
#>
param(
  [switch]$DryRun,
  [switch]$SkipCleanup,
  [switch]$SkillOnly,
  [string]$ApiKey = ""
)
$ErrorActionPreference = "Stop"
$SkillDir = Join-Path $env:USERPROFILE ".config\opencode\skills\mem0-opencode-setup"
$files = @(
  @{ path = 'SKILL.md'; data = '' }
  @{ path = 'README.md'; data = '' }
  @{ path = 'install.ps1'; data = '' }
  @{ path = 'files\memory-protocol.md'; data = '' }
  @{ path = 'files\mem0-memory.js'; data = '' }
  @{ path = 'files\opencode-mem0.snippet.jsonc'; data = '' }
)
Write-Host "Installing skill -> $SkillDir"
foreach ($e in $files) {
  $dst = Join-Path $SkillDir $e.path
  New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dst) | Out-Null
  [System.IO.File]::WriteAllBytes($dst, [Convert]::FromBase64String($e.data))
  Write-Host ("   + " + $e.path)
}
if ($SkillOnly) { Write-Host "Skill installed (setup skipped: -SkillOnly)."; exit 0 }

$installer = Join-Path $SkillDir "install.ps1"
$installArgs = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", $installer)
if ($DryRun) { $installArgs += "-DryRun" }
if ($SkipCleanup) { $installArgs += "-SkipCleanup" }
if ($ApiKey) { $installArgs += @("-ApiKey", $ApiKey) }
& powershell @installArgs